CREATE TABLE `zonas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `parroquia_id` bigint unsigned DEFAULT NULL,
  `nombre_zona` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `est_parroquia` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `num_elec_zona` bigint unsigned DEFAULT NULL,
  `num_elec_hombres_zona` bigint unsigned DEFAULT NULL,
  `num_elec_mujeres_zona` bigint unsigned DEFAULT NULL,
  `num_juntas` bigint unsigned DEFAULT NULL,
  `num_junta_hombre` bigint unsigned DEFAULT NULL,
  `num_junta_mujeres` bigint unsigned DEFAULT NULL,
  `num_elec_zona_max` bigint unsigned DEFAULT NULL,
  `num_junta_mujeres_ini` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `num_junta_mujeres_fin` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `num_junta_hombre_ini` bigint unsigned DEFAULT NULL,
  `num_junta_hombre_fin` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
