DELIMITER ;;
CREATE DEFINER=`root`@`%` FUNCTION `crear_juntas_x_recintos`() RETURNS tinyint(1)
    DETERMINISTIC
BEGIN
	DECLARE idr integer;
    DECLARE zona_idr integer;
    DECLARE ini integer;
    DECLARE fin integer;
    DECLARE done INT DEFAULT 0;
    DECLARE cur1 CURSOR FOR SELECT id, zona_id FROM recintos;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
    OPEN cur1;
    REPEAT
    FETCH cur1 INTO idr, zona_idr;
		IF NOT done THEN
			/* MUJERES */
			SET ini = 0;
            SET fin = 0;
            SELECT jun_ini_f FROM recintos WHERE id = idr INTO ini;
            SELECT jun_fin_f FROM recintos WHERE id = idr INTO fin;
            WHILE ini <= fin DO
				INSERT INTO juntas(zona_id, num_junta, genero, recinto_id) VALUES (zona_idr, ini, 'F', idr);
                SET ini=ini + 1;
			END WHILE;
            /* HOMBRES */
            SET ini = 0;
            SET fin = 0;
            SELECT jun_ini_m FROM recintos WHERE id = idr INTO ini;
            SELECT jun_fin_m FROM recintos WHERE id = idr INTO fin;
            WHILE ini <= fin DO
				INSERT INTO juntas(zona_id, num_junta, genero, recinto_id) VALUES (zona_idr,ini,'M',idr);
                SET ini=ini + 1;
			END WHILE;
		END IF;
	UNTIL done END REPEAT;
    CLOSE cur1;
    RETURN true;
END ;;
DELIMITER ;
