/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `getAvanceEscrutinio`()
BEGIN
	SELECT *, COALESCE((
		SELECT COUNT(cant.id) FROM actas AS ac
		LEFT JOIN cantones AS cant ON ac.canton_id = cant.id
		LEFT JOIN dignidades AS di ON di.id = ac.dignidad_id
		WHERE cant.id = c.id AND di.id = d.id
		GROUP BY cant.id, di.id
		), 0) AS ingresadas,
		(SELECT COUNT(*) FROM juntas AS j
		INNER JOIN zonas AS z ON j.zona_id = z.id
		INNER JOIN parroquias AS p ON p.id = z.parroquia_id
		INNER JOIN cantones AS cant ON cant.id = p.canton_id
		WHERE cant.id = c.id) AS total
	FROM cantones AS c, dignidades AS d
	WHERE c.id <> 3 AND d.activo = 1
	ORDER BY d.id, c.id;
END ;;
DELIMITER ;
