DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `sp_contar_actas`(IN p_user_id INT)
BEGIN
 SELECT 
        SUM(CASE WHEN user_add = p_user_id THEN 1 ELSE 0 END) AS total_ingresadas_add,
        SUM(CASE WHEN user_update = p_user_id THEN 1 ELSE 0 END) AS total_ingresadas_update
    FROM votaciones.actas;
END ;;
